STATIC_FILES = {
    'css/style.css': '@import url(\'https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@400;500;600;700&family=Inter:wght@300;400;500;600&display=swap\');\n\n/* ==================== VARIABLES ==================== */\n:root {\n    --gold: #c9a84c;\n    --gold-light: #e8c97a;\n    --gold-dark: #9a7a30;\n    --black: #0a0a0a;\n    --dark: #111111;\n    --dark-2: #1a1a1a;\n    --dark-3: #242424;\n    --white: #ffffff;\n    --gray: #888888;\n    --gray-light: #cccccc;\n    --bg: #f5f3ee;\n    --bg-2: #ede9e0;\n    --text: #1a1a1a;\n    --text-light: #666666;\n    --border: #e0d9cc;\n    --shadow: 0 4px 32px rgba(0,0,0,0.08);\n    --shadow-lg: 0 16px 64px rgba(0,0,0,0.14);\n    --radius: 4px;\n    --transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);\n}\n\n/* ==================== RESET ==================== */\n*, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }\nhtml { scroll-behavior: smooth; font-size: 16px; }\nbody {\n    font-family: \'Inter\', sans-serif;\n    background: var(--bg);\n    color: var(--text);\n    line-height: 1.6;\n}\nh1, h2, h3, h4 {\n    font-family: \'Cormorant Garamond\', serif;\n    line-height: 1.2;\n    font-weight: 600;\n}\na { text-decoration: none; color: inherit; transition: var(--transition); }\nimg { max-width: 100%; display: block; }\ninput, select, textarea, button { font-family: \'Inter\', sans-serif; }\n\n/* ==================== HEADER ==================== */\n.header {\n    background: var(--dark);\n    color: var(--white);\n    padding: 0;\n    border-bottom: 1px solid rgba(201,168,76,0.3);\n}\n\n.header-top {\n    background: var(--gold);\n    padding: 7px 0;\n    text-align: center;\n    font-size: 12px;\n    font-weight: 500;\n    letter-spacing: 1px;\n    text-transform: uppercase;\n    color: var(--dark);\n}\n\n.header-main {\n    max-width: 1280px;\n    margin: 0 auto;\n    padding: 20px 32px;\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n}\n\n.logo {\n    display: flex;\n    flex-direction: column;\n    gap: 2px;\n}\n\n.logo-main {\n    font-family: \'Cormorant Garamond\', serif;\n    font-size: 26px;\n    font-weight: 700;\n    color: var(--white);\n    letter-spacing: 2px;\n    text-transform: uppercase;\n}\n\n.logo-main span {\n    color: var(--gold);\n}\n\n.logo-sub {\n    font-size: 10px;\n    letter-spacing: 4px;\n    text-transform: uppercase;\n    color: var(--gray);\n    font-weight: 300;\n}\n\n.header-contact {\n    display: flex;\n    gap: 24px;\n    align-items: center;\n}\n\n.header-contact a {\n    color: var(--gray-light);\n    font-size: 13px;\n    font-weight: 400;\n    display: flex;\n    align-items: center;\n    gap: 8px;\n    transition: var(--transition);\n}\n\n.header-contact a:hover {\n    color: var(--gold);\n}\n\n.header-contact .whatsapp-btn {\n    background: var(--gold);\n    color: var(--dark);\n    padding: 9px 20px;\n    border-radius: var(--radius);\n    font-weight: 600;\n    font-size: 13px;\n    letter-spacing: 0.5px;\n}\n\n.header-contact .whatsapp-btn:hover {\n    background: var(--gold-light);\n    color: var(--dark);\n}\n\n/* ==================== NAVIGATION ==================== */\n.nav {\n    background: var(--dark-2);\n    border-bottom: 1px solid rgba(201,168,76,0.2);\n    position: sticky;\n    top: 0;\n    z-index: 1000;\n}\n\n.nav-content {\n    max-width: 1280px;\n    margin: 0 auto;\n    padding: 0 32px;\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n}\n\n.nav-links {\n    display: flex;\n    align-items: center;\n    gap: 0;\n}\n\n.nav-links a {\n    color: var(--gray-light);\n    padding: 18px 20px;\n    font-size: 13px;\n    font-weight: 500;\n    letter-spacing: 1px;\n    text-transform: uppercase;\n    border-bottom: 2px solid transparent;\n    transition: var(--transition);\n    white-space: nowrap;\n}\n\n.nav-links a:hover {\n    color: var(--gold);\n    background: rgba(201,168,76,0.05);\n}\n\n.nav-links a.active {\n    color: var(--gold);\n    border-bottom-color: var(--gold);\n}\n\n.nav-cart {\n    display: flex;\n    align-items: center;\n    gap: 16px;\n}\n\n.cart-link {\n    color: var(--gray-light) !important;\n    display: flex;\n    align-items: center;\n    gap: 8px;\n    font-size: 13px;\n    font-weight: 500;\n    letter-spacing: 1px;\n    text-transform: uppercase;\n    padding: 18px 0 !important;\n}\n\n.cart-link:hover {\n    color: var(--gold) !important;\n}\n\n/* ==================== HAMBURGER MENU ==================== */\n.hamburger {\n    display: none;\n    flex-direction: column;\n    gap: 5px;\n    cursor: pointer;\n    padding: 16px 0;\n    background: none;\n    border: none;\n    outline: none;\n}\n\n.hamburger span {\n    display: block;\n    width: 24px;\n    height: 2px;\n    background: var(--gray-light);\n    transition: var(--transition);\n    border-radius: 2px;\n}\n\n.hamburger.open span:nth-child(1) {\n    transform: translateY(7px) rotate(45deg);\n    background: var(--gold);\n}\n\n.hamburger.open span:nth-child(2) {\n    opacity: 0;\n}\n\n.hamburger.open span:nth-child(3) {\n    transform: translateY(-7px) rotate(-45deg);\n    background: var(--gold);\n}\n\n/* Mobile menu overlay */\n.mobile-menu {\n    display: none;\n    position: fixed;\n    top: 0;\n    left: 0;\n    right: 0;\n    bottom: 0;\n    background: var(--dark);\n    z-index: 2000;\n    flex-direction: column;\n    padding: 40px 32px;\n    overflow-y: auto;\n}\n\n.mobile-menu.open {\n    display: flex;\n}\n\n.mobile-menu-header {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    margin-bottom: 48px;\n    padding-bottom: 24px;\n    border-bottom: 1px solid rgba(201,168,76,0.2);\n}\n\n.mobile-menu-close {\n    background: none;\n    border: none;\n    color: var(--gray);\n    font-size: 28px;\n    cursor: pointer;\n    padding: 4px;\n    line-height: 1;\n    transition: var(--transition);\n}\n\n.mobile-menu-close:hover {\n    color: var(--gold);\n}\n\n.mobile-nav-links {\n    display: flex;\n    flex-direction: column;\n    gap: 0;\n    flex: 1;\n}\n\n.mobile-nav-links a {\n    color: var(--white);\n    font-family: \'Cormorant Garamond\', serif;\n    font-size: 24px;\n    font-weight: 600;\n    padding: 14px 0;\n    border-bottom: 1px solid rgba(255,255,255,0.06);\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    transition: var(--transition);\n}\n\n.mobile-nav-links a::after {\n    content: \'→\';\n    color: var(--gold);\n    font-size: 20px;\n    opacity: 0;\n    transform: translateX(-8px);\n    transition: var(--transition);\n}\n\n.mobile-nav-links a:hover {\n    color: var(--gold);\n    padding-left: 8px;\n}\n\n.mobile-nav-links a:hover::after {\n    opacity: 1;\n    transform: translateX(0);\n}\n\n.mobile-contact-info {\n    margin-top: 40px;\n    padding-top: 32px;\n    border-top: 1px solid rgba(201,168,76,0.2);\n}\n\n.mobile-contact-info a {\n    color: var(--gray);\n    font-size: 14px;\n    display: block;\n    margin-bottom: 12px;\n    transition: var(--transition);\n}\n\n.mobile-contact-info a:hover {\n    color: var(--gold);\n}\n\n/* ==================== MAIN ==================== */\n.main {\n    min-height: 60vh;\n    padding: 56px 0;\n}\n\n.container {\n    max-width: 1280px;\n    margin: 0 auto;\n    padding: 0 32px;\n}\n\n/* ==================== ALERTS ==================== */\n.alert {\n    padding: 14px 20px;\n    border-radius: var(--radius);\n    margin-bottom: 24px;\n    font-weight: 500;\n    font-size: 14px;\n    border-left: 3px solid;\n    display: flex;\n    align-items: center;\n    gap: 10px;\n}\n\n.alert-success { background: #f0faf6; color: #1a6b45; border-color: #2d9966; }\n.alert-error { background: #fdf2f2; color: #7b1a1a; border-color: #cc3333; }\n.alert-info { background: #f0f6ff; color: #1a3a6b; border-color: #3366cc; }\n\n/* ==================== PAGE HEADER ==================== */\n.page-header {\n    text-align: center;\n    margin-bottom: 56px;\n    padding-bottom: 40px;\n    position: relative;\n}\n\n.page-header::after {\n    content: \'\';\n    display: block;\n    width: 48px;\n    height: 2px;\n    background: var(--gold);\n    margin: 16px auto 0;\n}\n\n.page-header h1 {\n    font-size: clamp(32px, 5vw, 52px);\n    color: var(--dark);\n    margin-bottom: 12px;\n    font-weight: 600;\n}\n\n.page-header p {\n    color: var(--text-light);\n    font-size: 16px;\n    max-width: 560px;\n    margin: 0 auto;\n    line-height: 1.7;\n}\n\n/* ==================== BUTTONS ==================== */\n.btn {\n    display: inline-flex;\n    align-items: center;\n    gap: 8px;\n    padding: 13px 32px;\n    font-size: 13px;\n    font-weight: 600;\n    letter-spacing: 1px;\n    text-transform: uppercase;\n    cursor: pointer;\n    transition: var(--transition);\n    border: none;\n    outline: none;\n    border-radius: var(--radius);\n    font-family: \'Inter\', sans-serif;\n}\n\n.btn-gold {\n    background: var(--gold);\n    color: var(--dark);\n}\n\n.btn-gold:hover {\n    background: var(--gold-light);\n    transform: translateY(-1px);\n    box-shadow: 0 8px 24px rgba(201,168,76,0.3);\n    color: var(--dark);\n}\n\n.btn-dark {\n    background: var(--dark);\n    color: var(--white);\n    border: 1px solid var(--dark-3);\n}\n\n.btn-dark:hover {\n    background: var(--dark-2);\n    color: var(--gold);\n}\n\n.btn-outline {\n    background: transparent;\n    color: var(--dark);\n    border: 2px solid var(--dark);\n}\n\n.btn-outline:hover {\n    background: var(--dark);\n    color: var(--white);\n}\n\n.btn-outline-gold {\n    background: transparent;\n    color: var(--gold);\n    border: 1px solid var(--gold);\n}\n\n.btn-outline-gold:hover {\n    background: var(--gold);\n    color: var(--dark);\n}\n\n.btn-full {\n    width: 100%;\n    justify-content: center;\n    padding: 15px 32px;\n    font-size: 14px;\n}\n\n/* ==================== FORMS ==================== */\n.form-section {\n    background: var(--white);\n    padding: 48px;\n    border-radius: var(--radius);\n    box-shadow: var(--shadow);\n    border: 1px solid var(--border);\n}\n\n.form-title {\n    font-size: 28px;\n    color: var(--dark);\n    margin-bottom: 36px;\n    padding-bottom: 20px;\n    border-bottom: 1px solid var(--border);\n    font-family: \'Cormorant Garamond\', serif;\n}\n\n.form-group {\n    margin-bottom: 24px;\n}\n\n.form-group label {\n    display: block;\n    font-weight: 600;\n    font-size: 11px;\n    color: var(--dark);\n    margin-bottom: 8px;\n    text-transform: uppercase;\n    letter-spacing: 1.5px;\n}\n\n.form-group label .required {\n    color: #cc3333;\n    margin-left: 2px;\n}\n\n.form-control {\n    width: 100%;\n    padding: 13px 16px;\n    border: 1px solid var(--border);\n    border-radius: var(--radius);\n    font-size: 15px;\n    font-family: \'Inter\', sans-serif;\n    color: var(--text);\n    background: var(--white);\n    transition: var(--transition);\n    appearance: none;\n    -webkit-appearance: none;\n    outline: none;\n}\n\n.form-control:focus {\n    border-color: var(--gold);\n    box-shadow: 0 0 0 3px rgba(201,168,76,0.12);\n}\n\n.form-control::placeholder {\n    color: #bbb;\n    font-size: 14px;\n}\n\ntextarea.form-control {\n    min-height: 130px;\n    resize: vertical;\n}\n\nselect.form-control {\n    background-image: url("data:image/svg+xml,%3csvg xmlns=\'http://www.w3.org/2000/svg\' viewBox=\'0 0 16 16\'%3e%3cpath fill=\'none\' stroke=\'%23888\' stroke-linecap=\'round\' stroke-linejoin=\'round\' stroke-width=\'1.5\' d=\'M2 5l6 6 6-6\'/%3e%3c/svg%3e");\n    background-repeat: no-repeat;\n    background-position: right 14px center;\n    background-size: 14px;\n    padding-right: 44px;\n    cursor: pointer;\n}\n\n.form-row {\n    display: grid;\n    grid-template-columns: 1fr 1fr;\n    gap: 24px;\n}\n\n.form-actions {\n    display: flex;\n    gap: 14px;\n    margin-top: 36px;\n}\n\n/* ==================== CARDS ==================== */\n.grid-3 {\n    display: grid;\n    grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));\n    gap: 28px;\n}\n\n.grid-2 {\n    display: grid;\n    grid-template-columns: 1fr 1fr;\n    gap: 28px;\n}\n\n.card {\n    background: var(--white);\n    border-radius: var(--radius);\n    overflow: hidden;\n    box-shadow: var(--shadow);\n    border: 1px solid var(--border);\n    transition: var(--transition);\n}\n\n.card:hover {\n    transform: translateY(-4px);\n    box-shadow: var(--shadow-lg);\n}\n\n.card-img {\n    width: 100%;\n    height: 240px;\n    object-fit: cover;\n}\n\n.card-img-placeholder {\n    width: 100%;\n    height: 240px;\n    background: var(--dark);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    color: var(--gold);\n    font-size: 48px;\n}\n\n.card-body {\n    padding: 24px;\n}\n\n.card-title {\n    font-family: \'Cormorant Garamond\', serif;\n    font-size: 22px;\n    font-weight: 600;\n    color: var(--dark);\n    margin-bottom: 8px;\n    line-height: 1.3;\n}\n\n.card-text {\n    color: var(--text-light);\n    font-size: 14px;\n    line-height: 1.7;\n    margin-bottom: 20px;\n}\n\n.card-price {\n    font-family: \'Cormorant Garamond\', serif;\n    font-size: 30px;\n    font-weight: 700;\n    color: var(--gold-dark);\n    margin-bottom: 16px;\n}\n\n.card-location {\n    color: var(--text-light);\n    font-size: 12px;\n    margin-bottom: 14px;\n    display: flex;\n    align-items: center;\n    gap: 4px;\n    text-transform: uppercase;\n    letter-spacing: 0.5px;\n}\n\n.card-footer {\n    padding: 16px 24px;\n    border-top: 1px solid var(--border);\n    background: var(--bg);\n    display: flex;\n    gap: 10px;\n    align-items: center;\n    justify-content: space-between;\n}\n\n/* ==================== BADGES ==================== */\n.badge {\n    display: inline-flex;\n    align-items: center;\n    padding: 4px 12px;\n    border-radius: 2px;\n    font-size: 11px;\n    font-weight: 600;\n    text-transform: uppercase;\n    letter-spacing: 1px;\n}\n\n.badge-success { background: #e8f5ef; color: #1a6b45; }\n.badge-danger { background: #fdf0f0; color: #7b1a1a; }\n.badge-gold { background: rgba(201,168,76,0.12); color: var(--gold-dark); }\n.badge-dark { background: var(--dark); color: var(--white); }\n\n/* ==================== HERO ==================== */\n.hero {\n    background: var(--dark);\n    color: var(--white);\n    padding: 100px 32px;\n    text-align: center;\n    position: relative;\n    overflow: hidden;\n    margin-bottom: 80px;\n}\n\n.hero::before {\n    content: \'\';\n    position: absolute;\n    top: 0; left: 0; right: 0; bottom: 0;\n    background:\n        radial-gradient(ellipse 800px 500px at 50% 0%, rgba(201,168,76,0.14) 0%, transparent 60%),\n        linear-gradient(135deg, rgba(201,168,76,0.06) 0%, transparent 50%, rgba(201,168,76,0.04) 100%);\n    pointer-events: none;\n}\n\n.hero::after {\n    content: \'\';\n    position: absolute;\n    bottom: 0; left: 0; right: 0;\n    height: 1px;\n    background: linear-gradient(90deg, transparent, var(--gold), transparent);\n    opacity: 0.5;\n}\n\n.hero-label {\n    font-size: 11px;\n    letter-spacing: 4px;\n    text-transform: uppercase;\n    color: var(--gold);\n    margin-bottom: 24px;\n    font-weight: 500;\n}\n\n.hero h1 {\n    font-size: clamp(38px, 7vw, 72px);\n    color: var(--white);\n    margin-bottom: 24px;\n    line-height: 1.1;\n    max-width: 800px;\n    margin-left: auto;\n    margin-right: auto;\n}\n\n.hero h1 span {\n    color: var(--gold);\n}\n\n.hero p {\n    font-size: 17px;\n    color: rgba(255,255,255,0.65);\n    margin-bottom: 44px;\n    max-width: 560px;\n    margin-left: auto;\n    margin-right: auto;\n    line-height: 1.8;\n}\n\n.hero-btns {\n    display: flex;\n    gap: 16px;\n    justify-content: center;\n    flex-wrap: wrap;\n}\n\n/* ==================== STATS ==================== */\n.stats {\n    display: grid;\n    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));\n    gap: 1px;\n    background: var(--border);\n    border: 1px solid var(--border);\n    margin-bottom: 80px;\n    border-radius: var(--radius);\n    overflow: hidden;\n}\n\n.stat-card {\n    background: var(--white);\n    padding: 40px 24px;\n    text-align: center;\n    transition: var(--transition);\n}\n\n.stat-card:hover {\n    background: var(--dark);\n}\n\n.stat-card:hover .stat-value {\n    color: var(--gold);\n}\n\n.stat-card:hover .stat-label {\n    color: rgba(255,255,255,0.6);\n}\n\n.stat-value {\n    font-family: \'Cormorant Garamond\', serif;\n    font-size: 52px;\n    font-weight: 700;\n    color: var(--dark);\n    line-height: 1;\n    margin-bottom: 8px;\n    transition: var(--transition);\n}\n\n.stat-label {\n    color: var(--text-light);\n    font-size: 12px;\n    font-weight: 600;\n    text-transform: uppercase;\n    letter-spacing: 2px;\n    transition: var(--transition);\n}\n\n/* ==================== SECTION TITLES ==================== */\n.section-header {\n    text-align: center;\n    margin-bottom: 48px;\n}\n\n.section-label {\n    font-size: 11px;\n    letter-spacing: 4px;\n    text-transform: uppercase;\n    color: var(--gold-dark);\n    margin-bottom: 12px;\n    font-weight: 600;\n    display: block;\n}\n\n.section-title {\n    font-family: \'Cormorant Garamond\', serif;\n    font-size: clamp(28px, 4vw, 44px);\n    color: var(--dark);\n    font-weight: 600;\n    line-height: 1.2;\n}\n\n.section-line {\n    width: 48px;\n    height: 2px;\n    background: var(--gold);\n    margin: 16px auto 0;\n}\n\n/* ==================== INFO BOX ==================== */\n.info-box {\n    background: rgba(201,168,76,0.08);\n    border-left: 3px solid var(--gold);\n    padding: 16px 20px;\n    border-radius: var(--radius);\n    margin-bottom: 32px;\n    color: var(--gold-dark);\n    font-size: 14px;\n    font-weight: 500;\n}\n\n/* ==================== CONTACT ==================== */\n.contact-grid {\n    display: grid;\n    grid-template-columns: 1fr 1fr;\n    gap: 48px;\n    align-items: start;\n}\n\n.contact-info-box {\n    background: var(--dark);\n    color: var(--white);\n    padding: 48px;\n    border-radius: var(--radius);\n    border: 1px solid rgba(201,168,76,0.2);\n}\n\n.contact-info-box h2 {\n    font-family: \'Cormorant Garamond\', serif;\n    font-size: 32px;\n    color: var(--white);\n    margin-bottom: 36px;\n    padding-bottom: 20px;\n    border-bottom: 1px solid rgba(201,168,76,0.2);\n}\n\n.contact-item {\n    display: flex;\n    gap: 20px;\n    margin-bottom: 28px;\n    align-items: flex-start;\n}\n\n.contact-icon {\n    width: 44px;\n    height: 44px;\n    background: rgba(201,168,76,0.12);\n    border: 1px solid rgba(201,168,76,0.3);\n    border-radius: var(--radius);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    font-size: 18px;\n    flex-shrink: 0;\n}\n\n.contact-item strong {\n    display: block;\n    font-size: 10px;\n    text-transform: uppercase;\n    letter-spacing: 2px;\n    color: var(--gold);\n    margin-bottom: 6px;\n    font-weight: 600;\n}\n\n.contact-item a, .contact-item p {\n    color: rgba(255,255,255,0.8);\n    font-size: 15px;\n    line-height: 1.6;\n}\n\n.contact-item a:hover { color: var(--gold); }\n\n/* ==================== CART ==================== */\n.cart-item {\n    background: var(--white);\n    padding: 24px;\n    border-radius: var(--radius);\n    margin-bottom: 16px;\n    display: flex;\n    gap: 24px;\n    align-items: center;\n    border: 1px solid var(--border);\n    box-shadow: var(--shadow);\n}\n\n.cart-item img {\n    width: 90px;\n    height: 90px;\n    object-fit: cover;\n    border-radius: var(--radius);\n    flex-shrink: 0;\n}\n\n.cart-item-info { flex: 1; }\n\n.cart-item-name {\n    font-family: \'Cormorant Garamond\', serif;\n    font-size: 20px;\n    font-weight: 600;\n    margin-bottom: 6px;\n}\n\n.cart-item-price {\n    font-size: 22px;\n    font-weight: 700;\n    color: var(--gold-dark);\n    margin-bottom: 12px;\n}\n\n.qty-controls {\n    display: flex;\n    align-items: center;\n    gap: 0;\n    border: 1px solid var(--border);\n    border-radius: var(--radius);\n    overflow: hidden;\n    width: fit-content;\n}\n\n.qty-btn {\n    width: 36px;\n    height: 36px;\n    background: var(--bg);\n    border: none;\n    cursor: pointer;\n    font-size: 18px;\n    font-weight: 300;\n    color: var(--dark);\n    transition: var(--transition);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n}\n\n.qty-btn:hover { background: var(--dark); color: var(--white); }\n\n.qty-num {\n    width: 48px;\n    height: 36px;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    font-size: 14px;\n    font-weight: 600;\n    border-left: 1px solid var(--border);\n    border-right: 1px solid var(--border);\n}\n\n.cart-summary {\n    background: var(--white);\n    padding: 36px;\n    border-radius: var(--radius);\n    margin-top: 28px;\n    border: 1px solid var(--border);\n}\n\n.cart-total-line {\n    display: flex;\n    justify-content: space-between;\n    padding: 14px 0;\n    border-bottom: 1px solid var(--border);\n    font-size: 15px;\n}\n\n.cart-total-final {\n    font-family: \'Cormorant Garamond\', serif;\n    font-size: 26px;\n    font-weight: 700;\n    color: var(--dark);\n    padding-top: 16px;\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n}\n\n/* ==================== FOOTER ==================== */\n.footer {\n    background: var(--dark);\n    color: var(--white);\n    padding: 72px 0 0;\n    margin-top: 100px;\n    border-top: 1px solid rgba(201,168,76,0.2);\n}\n\n.footer-grid {\n    max-width: 1280px;\n    margin: 0 auto;\n    padding: 0 32px;\n    display: grid;\n    grid-template-columns: 2fr 1fr 1fr 1.5fr;\n    gap: 56px;\n    margin-bottom: 56px;\n}\n\n.footer-brand .logo-main { font-size: 22px; margin-bottom: 4px; }\n.footer-brand .logo-sub { margin-bottom: 20px; }\n\n.footer-brand p {\n    color: rgba(255,255,255,0.5);\n    font-size: 13px;\n    line-height: 1.8;\n    margin-bottom: 6px;\n}\n\n.footer h4 {\n    font-family: \'Inter\', sans-serif;\n    font-size: 11px;\n    font-weight: 700;\n    letter-spacing: 3px;\n    text-transform: uppercase;\n    color: var(--gold);\n    margin-bottom: 24px;\n}\n\n.footer nav a {\n    display: flex;\n    align-items: center;\n    gap: 8px;\n    color: rgba(255,255,255,0.5);\n    font-size: 14px;\n    margin-bottom: 13px;\n    transition: var(--transition);\n}\n\n.footer nav a:hover {\n    color: var(--gold);\n    transform: translateX(4px);\n}\n\n.footer-social {\n    display: flex;\n    gap: 10px;\n    margin-top: 24px;\n    flex-wrap: wrap;\n}\n\n.social-link {\n    padding: 8px 16px;\n    background: rgba(255,255,255,0.06);\n    border: 1px solid rgba(255,255,255,0.1);\n    border-radius: var(--radius);\n    color: rgba(255,255,255,0.6) !important;\n    font-size: 12px !important;\n    font-weight: 600;\n    letter-spacing: 0.5px;\n    transition: var(--transition) !important;\n    transform: none !important;\n}\n\n.social-link:hover {\n    background: rgba(201,168,76,0.15) !important;\n    border-color: var(--gold) !important;\n    color: var(--gold) !important;\n    transform: none !important;\n}\n\n/* Newsletter Footer */\n.newsletter-footer {\n    background: rgba(201,168,76,0.06);\n    border: 1px solid rgba(201,168,76,0.2);\n    padding: 28px;\n    border-radius: var(--radius);\n}\n\n.newsletter-footer p {\n    color: rgba(255,255,255,0.5);\n    font-size: 13px;\n    margin-bottom: 16px;\n    line-height: 1.6;\n}\n\n.nl-input {\n    width: 100%;\n    padding: 11px 14px;\n    background: rgba(255,255,255,0.06);\n    border: 1px solid rgba(255,255,255,0.12);\n    border-radius: var(--radius);\n    color: var(--white);\n    font-family: \'Inter\', sans-serif;\n    font-size: 14px;\n    outline: none;\n    transition: var(--transition);\n    margin-bottom: 10px;\n}\n\n.nl-input::placeholder { color: rgba(255,255,255,0.3); }\n.nl-input:focus { border-color: var(--gold); background: rgba(255,255,255,0.09); }\n.nl-input option { background: var(--dark); }\n\n.nl-btn {\n    width: 100%;\n    padding: 12px;\n    background: var(--gold);\n    color: var(--dark);\n    border: none;\n    border-radius: var(--radius);\n    font-weight: 700;\n    font-family: \'Inter\', sans-serif;\n    font-size: 12px;\n    letter-spacing: 1px;\n    text-transform: uppercase;\n    cursor: pointer;\n    transition: var(--transition);\n    margin-top: 4px;\n}\n\n.nl-btn:hover { background: var(--gold-light); }\n\n.footer-bottom {\n    border-top: 1px solid rgba(255,255,255,0.07);\n    padding: 24px 32px;\n    max-width: 1280px;\n    margin: 0 auto;\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    color: rgba(255,255,255,0.3);\n    font-size: 12px;\n}\n\n/* ==================== FILTERS ==================== */\n.filters {\n    display: flex;\n    gap: 8px;\n    justify-content: center;\n    margin-bottom: 40px;\n    flex-wrap: wrap;\n}\n\n.filter-btn {\n    padding: 9px 24px;\n    font-size: 12px;\n    font-weight: 600;\n    letter-spacing: 1px;\n    text-transform: uppercase;\n    background: var(--white);\n    color: var(--text-light);\n    border: 1px solid var(--border);\n    border-radius: var(--radius);\n    cursor: pointer;\n    transition: var(--transition);\n}\n\n.filter-btn:hover, .filter-btn.active {\n    background: var(--dark);\n    color: var(--gold);\n    border-color: var(--dark);\n}\n\n/* ==================== SUCCESS PAGE ==================== */\n.success-container {\n    max-width: 600px;\n    margin: 60px auto;\n    text-align: center;\n}\n\n.success-icon { font-size: 72px; margin-bottom: 24px; }\n\n.success-box {\n    background: var(--white);\n    padding: 56px;\n    border-radius: var(--radius);\n    box-shadow: var(--shadow-lg);\n    border: 1px solid var(--border);\n}\n\n.success-box h1 {\n    font-family: \'Cormorant Garamond\', serif;\n    font-size: 36px;\n    color: #1a6b45;\n    margin-bottom: 16px;\n}\n\n.order-number {\n    font-family: \'Cormorant Garamond\', serif;\n    font-size: 22px;\n    font-weight: 700;\n    color: var(--gold-dark);\n    margin: 24px 0;\n    padding: 16px;\n    background: var(--bg);\n    border-radius: var(--radius);\n    border: 1px dashed var(--gold);\n    letter-spacing: 2px;\n}\n\n/* ==================== EMPTY STATE ==================== */\n.empty-state {\n    text-align: center;\n    padding: 80px 20px;\n}\n\n.empty-icon {\n    font-size: 56px;\n    margin-bottom: 24px;\n    opacity: 0.3;\n}\n\n.empty-state h2 {\n    font-family: \'Cormorant Garamond\', serif;\n    font-size: 28px;\n    color: var(--dark);\n    margin-bottom: 12px;\n}\n\n.empty-state p {\n    color: var(--text-light);\n    margin-bottom: 28px;\n}\n\n/* ==================== PRODUCT DETAIL ==================== */\n.product-detail-grid {\n    display: grid;\n    grid-template-columns: 1fr 1fr;\n    gap: 56px;\n    align-items: start;\n}\n\n.product-main-img {\n    width: 100%;\n    border-radius: var(--radius);\n    box-shadow: var(--shadow-lg);\n}\n\n.product-title {\n    font-family: \'Cormorant Garamond\', serif;\n    font-size: 38px;\n    color: var(--dark);\n    margin-bottom: 16px;\n    line-height: 1.2;\n}\n\n.product-price-tag {\n    font-family: \'Cormorant Garamond\', serif;\n    font-size: 42px;\n    font-weight: 700;\n    color: var(--gold-dark);\n    margin: 24px 0;\n    line-height: 1;\n}\n\n/* ==================== RESPONSIVE ==================== */\n@media (max-width: 1024px) {\n    .footer-grid { grid-template-columns: 1fr 1fr; gap: 36px; }\n    .contact-grid { grid-template-columns: 1fr; }\n}\n\n@media (max-width: 768px) {\n    .header-main { padding: 16px 20px; }\n    .header-contact { display: none; }\n    .nav-content { padding: 0 20px; }\n    .nav-links { display: none; }\n    .hamburger { display: flex; }\n    .container { padding: 0 20px; }\n    .main { padding: 36px 0; }\n    .form-row { grid-template-columns: 1fr; gap: 0; }\n    .form-section { padding: 28px 20px; }\n    .grid-2 { grid-template-columns: 1fr; }\n    .product-detail-grid { grid-template-columns: 1fr; }\n    .footer-grid { grid-template-columns: 1fr; gap: 32px; }\n    .footer-bottom { flex-direction: column; gap: 8px; text-align: center; }\n    .hero { padding: 64px 20px; }\n    .stats { grid-template-columns: 1fr 1fr; }\n    .cart-item { flex-direction: column; align-items: flex-start; }\n}\n\n@media (max-width: 480px) {\n    .stats { grid-template-columns: 1fr; }\n    .filters { gap: 6px; }\n    .filter-btn { padding: 8px 16px; font-size: 11px; }\n    .hero h1 { font-size: 32px; }\n    .success-box { padding: 32px 20px; }\n}\n',
    'css/admin.css': "/* ====================================================\n   ADMIN.CSS — Layout complet du panel administrateur\n   ==================================================== */\n\n.admin-body {\n    display: flex;\n    min-height: 100vh;\n    background: var(--bg);\n    font-family: 'Inter', sans-serif;\n}\n\n/* ---------- Sidebar ---------- */\n.admin-sidebar {\n    width: 260px;\n    background: var(--black);\n    color: var(--white);\n    flex-shrink: 0;\n    display: flex;\n    flex-direction: column;\n    position: sticky;\n    top: 0;\n    height: 100vh;\n    overflow-y: auto;\n}\n\n.admin-sidebar .logo {\n    padding: 24px 20px;\n    border-bottom: 1px solid rgba(255,255,255,0.1);\n}\n\n.admin-sidebar .logo-main {\n    font-family: 'Cormorant Garamond', serif;\n    font-size: 22px;\n    font-weight: 700;\n}\n\n.admin-sidebar .logo-main span { color: var(--gold); }\n\n.admin-nav {\n    flex: 1;\n    padding: 16px 0;\n}\n\n.admin-nav a {\n    display: flex;\n    align-items: center;\n    gap: 12px;\n    padding: 12px 20px;\n    color: rgba(255,255,255,0.7);\n    font-size: 14px;\n    transition: var(--transition);\n    border-left: 3px solid transparent;\n}\n\n.admin-nav a:hover,\n.admin-nav a.active {\n    background: rgba(201,168,76,0.1);\n    color: var(--gold);\n    border-left-color: var(--gold);\n}\n\n.admin-sidebar-footer {\n    padding: 16px 20px;\n    border-top: 1px solid rgba(255,255,255,0.1);\n}\n\n.admin-sidebar-footer a {\n    color: rgba(255,255,255,0.6);\n    font-size: 13px;\n}\n\n.admin-sidebar-footer a:hover { color: var(--gold); }\n\n/* ---------- Zone de contenu ---------- */\n.admin-main {\n    flex: 1;\n    padding: 32px;\n    max-width: 100%;\n    overflow-x: auto;\n}\n\n.admin-content { width: 100%; }\n\n.content-header {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    margin-bottom: 24px;\n    flex-wrap: wrap;\n    gap: 12px;\n}\n\n.content-header h1 {\n    font-size: 26px;\n    color: var(--black);\n}\n\n/* ---------- Tableaux ---------- */\n.table-container {\n    background: var(--white);\n    border-radius: var(--radius);\n    box-shadow: var(--shadow);\n    overflow-x: auto;\n}\n\n.data-table {\n    width: 100%;\n    border-collapse: collapse;\n}\n\n.data-table th {\n    background: var(--bg-2);\n    text-align: left;\n    padding: 14px 16px;\n    font-size: 12px;\n    text-transform: uppercase;\n    letter-spacing: 0.5px;\n    color: var(--text-light);\n}\n\n.data-table td {\n    padding: 14px 16px;\n    border-top: 1px solid var(--border);\n    font-size: 14px;\n}\n\n.data-table tr:hover { background: rgba(201,168,76,0.03); }\n\n/* ---------- Cartes statistiques (dashboard) ---------- */\n.stats-grid {\n    display: grid;\n    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));\n    gap: 20px;\n    margin-bottom: 32px;\n}\n\n.stat-card {\n    background: var(--white);\n    padding: 24px;\n    border-radius: var(--radius);\n    box-shadow: var(--shadow);\n    border-left: 4px solid var(--gold);\n}\n\n.stat-card .stat-value {\n    font-size: 32px;\n    font-weight: 700;\n    color: var(--black);\n    font-family: 'Cormorant Garamond', serif;\n}\n\n.stat-card .stat-label {\n    font-size: 13px;\n    color: var(--text-light);\n    margin-top: 4px;\n}\n\n.stat-card.alert { border-left-color: #dc3545; }\n.stat-card.alert .stat-value { color: #dc3545; }\n\n/* ---------- Login admin ---------- */\n.admin-login-page {\n    min-height: 100vh;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    background: var(--black);\n    padding: 20px;\n}\n\n.admin-login-box {\n    background: var(--white);\n    padding: 48px 40px;\n    border-radius: 8px;\n    width: 100%;\n    max-width: 400px;\n    box-shadow: 0 20px 60px rgba(0,0,0,0.3);\n}\n\n.admin-login-box .logo-main {\n    text-align: center;\n    font-family: 'Cormorant Garamond', serif;\n    font-size: 28px;\n    margin-bottom: 8px;\n}\n\n.admin-login-box .logo-main span { color: var(--gold); }\n\n.admin-login-box p.subtitle {\n    text-align: center;\n    color: var(--text-light);\n    margin-bottom: 32px;\n    font-size: 13px;\n    letter-spacing: 1px;\n    text-transform: uppercase;\n}\n\n/* ---------- Empty states ---------- */\n.empty-state {\n    text-align: center;\n    padding: 60px 20px;\n    color: var(--gray);\n}\n\n.empty-state i { font-size: 48px; color: var(--gold); margin-bottom: 16px; display: block; }\n\n/* ---------- Formulaires admin ---------- */\n.admin-form-container {\n    background: var(--white);\n    padding: 32px;\n    border-radius: var(--radius);\n    box-shadow: var(--shadow);\n    max-width: 700px;\n}\n\n.form-row-2 {\n    display: grid;\n    grid-template-columns: 1fr 1fr;\n    gap: 16px;\n}\n\n.checkbox-group {\n    display: flex;\n    align-items: center;\n    gap: 8px;\n    margin: 16px 0;\n}\n\n.form-actions {\n    display: flex;\n    gap: 12px;\n    margin-top: 24px;\n}\n\n/* ---------- Hamburger mobile pour sidebar ---------- */\n.admin-mobile-toggle {\n    display: none;\n}\n\n@media (max-width: 900px) {\n    .admin-sidebar {\n        position: fixed;\n        left: -260px;\n        z-index: 1000;\n        transition: left 0.3s ease;\n    }\n\n    .admin-sidebar.open { left: 0; }\n\n    .admin-main { padding: 20px; padding-top: 70px; }\n\n    .admin-mobile-toggle {\n        display: flex;\n        position: fixed;\n        top: 16px; left: 16px;\n        z-index: 1001;\n        width: 44px; height: 44px;\n        background: var(--black);\n        color: var(--white);\n        border: none;\n        border-radius: 50%;\n        align-items: center;\n        justify-content: center;\n        font-size: 18px;\n        box-shadow: var(--shadow);\n    }\n\n    .form-row-2 { grid-template-columns: 1fr; }\n}\n",
    'css/enhancements.css': '/* ====================================================\n   ENHANCEMENTS.CSS — À charger APRÈS style.css dans base.html\n   Animations, transitions et finitions premium\n   ==================================================== */\n\n/* ---------- Polices (à lier dans le <head> si pas déjà fait) ---------- */\n/* <link rel="preconnect" href="https://fonts.googleapis.com">\n   <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n   <link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@400;500;600;700&family=Inter:wght@300;400;500;600;700&display=swap" rel="stylesheet"> */\n\n:root {\n    --gold: #c9a84c;\n    --gold-light: #e8c97a;\n    --gold-dark: #9a7a30;\n    --black: #0a0a0a;\n    --dark: #111111;\n    --ease-smooth: cubic-bezier(0.4, 0, 0.2, 1);\n}\n\n* {\n    scroll-behavior: smooth;\n}\n\nbody {\n    font-family: \'Inter\', sans-serif;\n}\n\nh1, h2, h3, h4, .font-display {\n    font-family: \'Cormorant Garamond\', serif;\n    letter-spacing: 0.5px;\n}\n\n/* ---------- Reveal au scroll ---------- */\n.reveal {\n    opacity: 0;\n    transform: translateY(24px);\n    transition: opacity 0.7s var(--ease-smooth), transform 0.7s var(--ease-smooth);\n}\n\n.reveal.is-visible {\n    opacity: 1;\n    transform: translateY(0);\n}\n\n.reveal-delay-1 { transition-delay: 0.1s; }\n.reveal-delay-2 { transition-delay: 0.2s; }\n.reveal-delay-3 { transition-delay: 0.3s; }\n\n/* ---------- Boutons ---------- */\n.btn {\n    position: relative;\n    overflow: hidden;\n    transition: transform 0.3s var(--ease-smooth), box-shadow 0.3s var(--ease-smooth);\n}\n\n.btn::after {\n    content: \'\';\n    position: absolute;\n    top: 50%; left: 50%;\n    width: 0; height: 0;\n    background: rgba(255,255,255,0.25);\n    border-radius: 50%;\n    transform: translate(-50%, -50%);\n    transition: width 0.5s ease, height 0.5s ease;\n}\n\n.btn:hover::after {\n    width: 300px;\n    height: 300px;\n}\n\n.btn:hover {\n    transform: translateY(-3px);\n    box-shadow: 0 10px 24px rgba(201, 168, 76, 0.3);\n}\n\n.btn:active {\n    transform: translateY(-1px);\n}\n\n/* ---------- Cartes produits / projets ---------- */\n.product-card, .project-card {\n    transition: transform 0.4s var(--ease-smooth), box-shadow 0.4s var(--ease-smooth);\n    will-change: transform;\n}\n\n.product-card:hover, .project-card:hover {\n    transform: translateY(-8px);\n    box-shadow: 0 20px 40px rgba(0,0,0,0.12);\n}\n\n.product-card img, .project-card img {\n    transition: transform 0.6s var(--ease-smooth), filter 0.4s ease;\n}\n\n.product-card:hover img, .project-card:hover img {\n    transform: scale(1.06);\n}\n\n/* ---------- Hero avec dégradé animé ---------- */\n.hero {\n    position: relative;\n    overflow: hidden;\n}\n\n.hero::before {\n    content: \'\';\n    position: absolute;\n    inset: 0;\n    background: linear-gradient(120deg, rgba(201,168,76,0.08), transparent 40%, rgba(201,168,76,0.05));\n    background-size: 200% 200%;\n    animation: gradientShift 12s ease infinite;\n    pointer-events: none;\n}\n\n@keyframes gradientShift {\n    0% { background-position: 0% 50%; }\n    50% { background-position: 100% 50%; }\n    100% { background-position: 0% 50%; }\n}\n\n.hero h1 {\n    animation: fadeInUp 1s var(--ease-smooth) both;\n}\n\n.hero p {\n    animation: fadeInUp 1s var(--ease-smooth) 0.2s both;\n}\n\n.hero .btn {\n    animation: fadeInUp 1s var(--ease-smooth) 0.4s both;\n}\n\n@keyframes fadeInUp {\n    from { opacity: 0; transform: translateY(20px); }\n    to { opacity: 1; transform: translateY(0); }\n}\n\n/* ---------- Menu hamburger animé ---------- */\n.hamburger-icon span {\n    transition: transform 0.3s var(--ease-smooth), opacity 0.3s var(--ease-smooth);\n}\n\n.hamburger-icon.active span:nth-child(1) {\n    transform: translateY(8px) rotate(45deg);\n}\n\n.hamburger-icon.active span:nth-child(2) {\n    opacity: 0;\n}\n\n.hamburger-icon.active span:nth-child(3) {\n    transform: translateY(-8px) rotate(-45deg);\n}\n\n.mobile-menu {\n    transition: max-height 0.4s var(--ease-smooth), opacity 0.3s ease;\n}\n\n/* ---------- Navigation ---------- */\n.navbar a {\n    position: relative;\n}\n\n.navbar a::after {\n    content: \'\';\n    position: absolute;\n    bottom: -4px; left: 0;\n    width: 0; height: 2px;\n    background: var(--gold);\n    transition: width 0.3s var(--ease-smooth);\n}\n\n.navbar a:hover::after,\n.navbar a.active::after {\n    width: 100%;\n}\n\n/* ---------- Compteurs statistiques ---------- */\n.stat-number {\n    font-variant-numeric: tabular-nums;\n}\n\n/* ---------- Formulaires ---------- */\ninput, textarea, select {\n    transition: border-color 0.3s ease, box-shadow 0.3s ease;\n}\n\ninput:focus, textarea:focus, select:focus {\n    border-color: var(--gold);\n    box-shadow: 0 0 0 4px rgba(201, 168, 76, 0.12);\n    outline: none;\n}\n\n/* ---------- Badge "En stock" pulsant ---------- */\n.badge-instock {\n    position: relative;\n    padding-left: 1.2rem;\n}\n\n.badge-instock::before {\n    content: \'\';\n    position: absolute;\n    left: 0.3rem; top: 50%;\n    width: 6px; height: 6px;\n    background: #2ecc71;\n    border-radius: 50%;\n    transform: translateY(-50%);\n    animation: pulse 2s ease infinite;\n}\n\n@keyframes pulse {\n    0% { box-shadow: 0 0 0 0 rgba(46, 204, 113, 0.5); }\n    70% { box-shadow: 0 0 0 8px rgba(46, 204, 113, 0); }\n    100% { box-shadow: 0 0 0 0 rgba(46, 204, 113, 0); }\n}\n\n/* ---------- Loader de page ---------- */\n.page-loader {\n    position: fixed;\n    inset: 0;\n    background: var(--black);\n    z-index: 9999;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    transition: opacity 0.5s ease, visibility 0.5s ease;\n}\n\n.page-loader.hidden {\n    opacity: 0;\n    visibility: hidden;\n}\n\n.page-loader .spinner {\n    width: 40px; height: 40px;\n    border: 3px solid rgba(201,168,76,0.2);\n    border-top-color: var(--gold);\n    border-radius: 50%;\n    animation: spin 0.8s linear infinite;\n}\n\n@keyframes spin {\n    to { transform: rotate(360deg); }\n}\n\n/* ---------- Retour en haut ---------- */\n.back-to-top {\n    position: fixed;\n    bottom: 24px; right: 24px;\n    width: 48px; height: 48px;\n    background: var(--gold);\n    color: white;\n    border-radius: 50%;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    box-shadow: 0 4px 16px rgba(0,0,0,0.2);\n    opacity: 0;\n    visibility: hidden;\n    transform: translateY(20px);\n    transition: all 0.3s var(--ease-smooth);\n    z-index: 999;\n    cursor: pointer;\n    border: none;\n}\n\n.back-to-top.visible {\n    opacity: 1;\n    visibility: visible;\n    transform: translateY(0);\n}\n\n.back-to-top:hover {\n    background: var(--gold-dark);\n    transform: translateY(-4px);\n}\n\n/* ---------- Lightbox (zoom image au clic) ---------- */\n.lightbox-img {\n    cursor: zoom-in;\n}\n\n.lightbox-overlay {\n    position: fixed;\n    inset: 0;\n    background: rgba(10, 10, 10, 0.92);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    z-index: 10000;\n    opacity: 0;\n    visibility: hidden;\n    transition: opacity 0.3s var(--ease-smooth), visibility 0.3s var(--ease-smooth);\n    padding: 24px;\n}\n\n.lightbox-overlay.open {\n    opacity: 1;\n    visibility: visible;\n}\n\n.lightbox-overlay img {\n    max-width: min(92vw, 1100px);\n    max-height: 88vh;\n    border-radius: 6px;\n    box-shadow: 0 20px 60px rgba(0,0,0,0.6);\n    transform: scale(0.92);\n    transition: transform 0.3s var(--ease-smooth);\n}\n\n.lightbox-overlay.open img {\n    transform: scale(1);\n}\n\n.lightbox-close {\n    position: absolute;\n    top: 20px; right: 24px;\n    width: 44px; height: 44px;\n    border-radius: 50%;\n    background: rgba(255,255,255,0.08);\n    color: var(--white, #fff);\n    border: 1px solid rgba(255,255,255,0.2);\n    font-size: 22px;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    cursor: pointer;\n    transition: background 0.3s ease;\n}\n\n.lightbox-close:hover {\n    background: var(--gold);\n    color: var(--black);\n}\n\n/* ---------- Logo image dans header/hero ---------- */\n.logo-image {\n    max-height: 48px;\n    width: auto;\n    display: block;\n    background: var(--white, #fff);\n    padding: 6px 10px;\n    border-radius: 8px;\n    box-shadow: 0 2px 8px rgba(0,0,0,0.25);\n}\n\n.hero-logo-wrap {\n    display: inline-flex;\n    align-items: center;\n    justify-content: center;\n    margin-bottom: 28px;\n    padding: 24px 48px;\n    border-radius: 20px;\n    background: var(--white, #fff);\n    box-shadow: 0 16px 48px rgba(0,0,0,0.35);\n}\n\n.hero-logo-wrap img {\n    max-height: 90px;\n    width: auto;\n}\n\n/* ---------- Accessibilité : réduire animations si demandé ---------- */\n@media (prefers-reduced-motion: reduce) {\n    *, *::before, *::after {\n        animation-duration: 0.01ms !important;\n        animation-iteration-count: 1 !important;\n        transition-duration: 0.01ms !important;\n        scroll-behavior: auto !important;\n    }\n}\n',
    'css/admin-buttons.css': '/* ====================================\n   STYLES BOUTONS SUPPRESSION & ACTIONS\n   À ajouter dans static/css/style.css\n   ==================================== */\n\n.actions-cell {\n    display: flex;\n    gap: 0.5rem;\n    align-items: center;\n    justify-content: flex-start;\n}\n\n.btn-sm {\n    padding: 0.4rem 0.8rem;\n    font-size: 0.875rem;\n    border-radius: 5px;\n    border: none;\n    cursor: pointer;\n    transition: all 0.3s ease;\n    color: white;\n    text-decoration: none;\n    display: inline-flex;\n    align-items: center;\n    justify-content: center;\n    font-weight: 500;\n}\n\n.btn-danger {\n    background-color: #dc3545;\n    color: white;\n}\n\n.btn-danger:hover {\n    background-color: #c82333;\n    transform: translateY(-2px);\n    box-shadow: 0 4px 8px rgba(220, 53, 69, 0.3);\n}\n\n.btn-secondary {\n    background-color: #6c757d;\n    color: white;\n}\n\n.btn-secondary:hover {\n    background-color: #5a6268;\n    transform: translateY(-2px);\n    box-shadow: 0 4px 8px rgba(108, 117, 125, 0.3);\n}\n\n.btn-primary {\n    background-color: #c9a84c;\n    color: white;\n}\n\n.btn-primary:hover {\n    background-color: #b89538;\n    transform: translateY(-2px);\n    box-shadow: 0 4px 8px rgba(201, 168, 76, 0.3);\n}\n\n.data-table td {\n    vertical-align: middle;\n}\n\n.table-thumbnail {\n    width: 60px;\n    height: 60px;\n    object-fit: cover;\n    border-radius: 5px;\n}\n\n.no-image {\n    width: 60px;\n    height: 60px;\n    background: #f0f0f0;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    font-size: 10px;\n    color: #999;\n    border-radius: 5px;\n}\n\n.badge {\n    padding: 0.25rem 0.75rem;\n    border-radius: 12px;\n    font-size: 0.75rem;\n    font-weight: 600;\n    text-transform: uppercase;\n}\n\n.badge-pending {\n    background-color: #ffc107;\n    color: #000;\n}\n\n.badge-confirmed {\n    background-color: #17a2b8;\n    color: white;\n}\n\n.badge-completed, .badge-delivered {\n    background-color: #28a745;\n    color: white;\n}\n\n.badge-cancelled {\n    background-color: #dc3545;\n    color: white;\n}\n\n.badge-sent {\n    background-color: #28a745;\n    color: white;\n}\n\n.badge-draft {\n    background-color: #6c757d;\n    color: white;\n}\n\n.badge-active {\n    background-color: #28a745;\n    color: white;\n}\n\n.badge-unsubscribed {\n    background-color: #dc3545;\n    color: white;\n}\n\n.badge-new {\n    background-color: #007bff;\n    color: white;\n}\n\n.badge-read {\n    background-color: #6c757d;\n    color: white;\n}\n\n.badge-replied {\n    background-color: #28a745;\n    color: white;\n}\n\n.badge-success {\n    background-color: #28a745;\n    color: white;\n}\n\n.badge-danger {\n    background-color: #dc3545;\n    color: white;\n}\n\n.badge-info {\n    background-color: #17a2b8;\n    color: white;\n}\n\n.empty-state {\n    text-align: center;\n    padding: 4rem 2rem;\n    color: #999;\n}\n\n.empty-state i {\n    color: #c9a84c;\n    margin-bottom: 1rem;\n}\n\n.empty-state p {\n    font-size: 1.2rem;\n    margin-bottom: 1.5rem;\n}\n',
    'js/animations.js': '// ====================================================\n// ANIMATIONS.JS — À charger avant </body> dans base.html\n// Reveal au scroll, loader, bouton retour en haut\n// ====================================================\n\ndocument.addEventListener(\'DOMContentLoaded\', function () {\n\n    // ---------- Reveal au scroll ----------\n    const revealElements = document.querySelectorAll(\'.reveal\');\n\n    if (\'IntersectionObserver\' in window && revealElements.length) {\n        const observer = new IntersectionObserver((entries) => {\n            entries.forEach(entry => {\n                if (entry.isIntersecting) {\n                    entry.target.classList.add(\'is-visible\');\n                    observer.unobserve(entry.target);\n                }\n            });\n        }, { threshold: 0.15, rootMargin: \'0px 0px -50px 0px\' });\n\n        revealElements.forEach(el => observer.observe(el));\n    } else {\n        // Fallback : navigateurs anciens\n        revealElements.forEach(el => el.classList.add(\'is-visible\'));\n    }\n\n    // ---------- Loader de page ----------\n    const loader = document.querySelector(\'.page-loader\');\n    if (loader) {\n        window.addEventListener(\'load\', () => {\n            setTimeout(() => loader.classList.add(\'hidden\'), 200);\n        });\n    }\n\n    // ---------- Bouton retour en haut ----------\n    const backToTop = document.querySelector(\'.back-to-top\');\n    if (backToTop) {\n        window.addEventListener(\'scroll\', () => {\n            if (window.scrollY > 400) {\n                backToTop.classList.add(\'visible\');\n            } else {\n                backToTop.classList.remove(\'visible\');\n            }\n        });\n\n        backToTop.addEventListener(\'click\', () => {\n            window.scrollTo({ top: 0, behavior: \'smooth\' });\n        });\n    }\n\n    // ---------- Menu hamburger mobile ----------\n    const hamburger = document.querySelector(\'.hamburger-icon\');\n    const mobileMenu = document.querySelector(\'.mobile-menu\');\n\n    if (hamburger && mobileMenu) {\n        hamburger.addEventListener(\'click\', () => {\n            hamburger.classList.toggle(\'active\');\n            mobileMenu.classList.toggle(\'open\');\n        });\n\n        // Fermer le menu au clic sur un lien\n        mobileMenu.querySelectorAll(\'a\').forEach(link => {\n            link.addEventListener(\'click\', () => {\n                hamburger.classList.remove(\'active\');\n                mobileMenu.classList.remove(\'open\');\n            });\n        });\n    }\n\n    // ---------- Compteurs animés (statistiques accueil) ----------\n    const counters = document.querySelectorAll(\'.stat-number[data-count]\');\n    if (counters.length && \'IntersectionObserver\' in window) {\n        const counterObserver = new IntersectionObserver((entries) => {\n            entries.forEach(entry => {\n                if (entry.isIntersecting) {\n                    animateCounter(entry.target);\n                    counterObserver.unobserve(entry.target);\n                }\n            });\n        }, { threshold: 0.5 });\n\n        counters.forEach(counter => counterObserver.observe(counter));\n    }\n\n    function animateCounter(el) {\n        const target = parseInt(el.getAttribute(\'data-count\'), 10);\n        const duration = 1500;\n        const start = performance.now();\n\n        function step(now) {\n            const progress = Math.min((now - start) / duration, 1);\n            const eased = 1 - Math.pow(1 - progress, 3);\n            el.textContent = Math.floor(eased * target);\n            if (progress < 1) requestAnimationFrame(step);\n            else el.textContent = target;\n        }\n        requestAnimationFrame(step);\n    }\n\n    // ---------- Lightbox (zoom image au clic) ----------\n    let lightbox = document.querySelector(\'.lightbox-overlay\');\n    if (!lightbox) {\n        lightbox = document.createElement(\'div\');\n        lightbox.className = \'lightbox-overlay\';\n        lightbox.innerHTML = \'<button class="lightbox-close" aria-label="Fermer">&times;</button><img src="" alt="">\';\n        document.body.appendChild(lightbox);\n    }\n    const lightboxImg = lightbox.querySelector(\'img\');\n    const lightboxClose = lightbox.querySelector(\'.lightbox-close\');\n\n    function openLightbox(src, alt) {\n        lightboxImg.src = src;\n        lightboxImg.alt = alt || \'\';\n        lightbox.classList.add(\'open\');\n        document.body.style.overflow = \'hidden\';\n    }\n\n    function closeLightbox() {\n        lightbox.classList.remove(\'open\');\n        document.body.style.overflow = \'\';\n    }\n\n    document.addEventListener(\'click\', function (e) {\n        const target = e.target.closest(\'.lightbox-img\');\n        if (target && target.tagName === \'IMG\') {\n            openLightbox(target.src, target.alt);\n        }\n    });\n\n    lightboxClose.addEventListener(\'click\', closeLightbox);\n    lightbox.addEventListener(\'click\', function (e) {\n        if (e.target === lightbox) closeLightbox();\n    });\n    document.addEventListener(\'keydown\', function (e) {\n        if (e.key === \'Escape\') closeLightbox();\n    });\n\n});\n',
}
